    'intro.origin': ['イギリス（インドのパチーシから）', 'England (from India’s Pachisi)', '英国（源自印度帕奇西）', '英國（源自印度帕奇西）', '영국 (인도의 파치시에서)', 'Inglaterra (del Pachisi indio)', 'Angleterre (d’après le Pachisi indien)', 'Inglaterra (do Pachisi indiano)', 'England (nach dem indischen Pachisi)', 'Англия (из индийской пачиси)', 'İngiltere (Hint Pachisi’sinden)', 'Inggris (dari Pachisi India)', 'इंग्लैंड (भारत के पचीसी से)', 'إنجلترا (من باتشيسي الهندية)'],
    'intro.players': ['2〜4人', '2–4', '2–4人', '2–4人', '2~4명', '2–4', '2 à 4', '2–4', '2–4', '2–4', '2–4', '2–4', '2–4', '2–4'],
